    "fix": "app.config[\"MAX_CONTENT_LENGTH\"] = 64 * 1024\n\ndef require_json(*fields):\n    data = request.get_json(silent=True)\n    if not isinstance(data, dict):\n        abort(400, \"expected a JSON object\")\n    missing = [f for f in fields\n               if not isinstance(data.get(f), str) or not data[f].strip()]\n    if missing:\n        abort(400, \"missing or malformed fields\")   # do not enumerate internals\n    return {f: data[f] for f in fields}\n\n# optional: schema validation for richer bodies\n#   from pydantic import BaseModel, HttpUrl, constr\n#   class LoginIn(BaseModel):\n#       username: constr(min_length=1, max_length=64, pattern=r\"^[\\w._-]+$\")\n#       password: constr(min_length=8, max_length=1024)",
